local function optional(f)local ok,v=pcall(f);return ok and v or{unavailable=tostring(v)}end
local function category(t,n)for k,v in pairs(t or{})do if k==n or v==n then return true end end;return false end
script.on_init(function()
 local name='orbital-trader';local p=assert(prototypes.entity[name]);local f=game.forces.player;local s=game.surfaces[1];s.request_to_generate_chunks({20,20},1);s.force_generate_chunk_requests();local tiles={};for x=10,40 do for y=10,40 do tiles[#tiles+1]={name='grass-1',position={x,y}}end end;s.set_tiles(tiles,true)
 local e=assert(s.create_entity{name=name,position={20,20},force=f});local dirs={};for _,d in ipairs({0,4,8,12})do e.direction=d;dirs[#dirs+1]={requested=d,actual=e.direction,can_place=s.can_place_entity{name=name,position={32,20},direction=d,force=f}}end;e.direction=0
 local pipes={};for i=1,e.fluids_count do pipes[#pipes+1]={index=i,capacity=e.get_fluid_capacity(i),connections=e.get_fluid_box_pipe_connections(i)}end

 local wires={};for id in pairs(e.get_wire_connectors(true)or{})do wires[#wires+1]=id end
 local recipes={};local names={};for n,r in pairs(prototypes.recipe)do if category(r.categories,'orbital-trader')then recipes[#recipes+1]={name=n,seconds=r.energy,ingredients=r.ingredients,products=r.products,categories=r.categories,enabled=f.recipes[n].enabled};names[n]=true end end
 table.sort(recipes,function(a,b)return a.name<b.name end);for _,row in ipairs(recipes)do e.set_recipe(row.name);row.native_input_slots=#e.get_inventory(defines.inventory.crafter_input);row.native_output_slots=#e.get_output_inventory();row.native_fluid_storage_count=e.fluids_count end;e.set_recipe(nil);names[name]=true;local unlocks={};for n,t in pairs(prototypes.technology)do local relevant={};for _,ef in pairs(t.effects or{})do if ef.type=='unlock-recipe'and names[ef.recipe]then relevant[#relevant+1]=ef.recipe end end;if #relevant>0 then local prerequisites={};for q in pairs(t.prerequisites)do prerequisites[#prerequisites+1]=q end;unlocks[#unlocks+1]={name=n,prerequisites=prerequisites,count=t.research_unit_count,ticks=t.research_unit_energy,ingredients=t.research_unit_ingredients,recipes=relevant}end end
 local item=prototypes.item[name];local r=prototypes.recipe[name];local report={entity={name=name,type=p.type,footprint={p.tile_width,p.tile_height},collision_box=p.collision_box,selection_box=p.selection_box,max_energy_usage_watts=p.get_max_energy_usage()*60,electric_source=optional(function()return {buffer=p.electric_energy_source_prototype.buffer_capacity,drain=p.electric_energy_source_prototype.drain*60}end),burner=not not e.burner,crafting_categories=p.crafting_categories,crafting_speed=e.crafting_speed,module_slots=optional(function()local inv=e.get_module_inventory();return inv and #inv or 0 end),result_inventory_slots=#e.get_output_inventory(),fluid_boxes=pipes,prototype_fluid_boxes=optional(function()local rows={};for i,fp in pairs(p.fluidbox_prototypes)do rows[#rows+1]={index=i,production_type=fp.production_type,pipe_connections=fp.pipe_connections}end;return rows end),circuit_connector_ids=wires,circuit_reach=p.get_max_circuit_wire_distance(),surface_conditions=p.surface_conditions},item={name=name,place_result=item.place_result.name,stack_size=item.stack_size,weight=item.weight},building_recipe={seconds=r.energy,categories=r.categories,ingredients=r.ingredients,products=r.products},processing_recipes=recipes,unlocks=unlocks,native_directions=dirs,normal_nauvis_placement=dirs[1].can_place,prototype_overrides=false}
 helpers.write_file('orbital-trader-contract/contract.json',helpers.table_to_json(report),false);log('ORBITAL_TRADER_ACTUAL_CONTRACT_CAPTURED')
end)
